package dev.dreamwalker.bloodbornedw.link;

import dev.dreamwalker.bloodbornedw.tool.ToolCommands;
import dev.dreamwalker.bloodbornedw.tool.ToolTarget;
import java.util.*;
import java.util.function.BiFunction;
import java.util.function.Function;
import java.util.function.Predicate;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.math.BlockPos;

/** WorldEdit-only typed reference preservation. Restore merges the affected
 * connected mechanism component into current data; unrelated components and
 * command counters are never replaced and no commands/events are executed. */
public final class WorldEditReferenceSnapshot {
    private WorldEditReferenceSnapshot() {}
    private static NbtCompound all(MinecraftServer server){
        var n=new NbtCompound();n.put("Links",MechanismState.get(server).writeNbt(new NbtCompound()));n.put("Rules",MechanismRules.migrationSnapshot(server));n.put("Groups",MechanismGroups.get(server).writeNbt(new NbtCompound()));n.put("Policies",ObjectPolicies.get(server).writeNbt(new NbtCompound()));n.put("Commands",ToolCommands.get(server).writeNbt(new NbtCompound()));return n;
    }
    private static UUID uuid(NbtElement raw){return NbtHelper.toUuid(raw);}
    private static NbtList filtered(NbtList in,Predicate<NbtCompound> predicate){var out=new NbtList();for(NbtElement raw:in){var row=(NbtCompound)raw;if(predicate.test(row))out.add(row.copy());}return out;}
    private static boolean related(NbtCompound row,Set<UUID> ids){
        if(row.containsUuid("Instance")&&ids.contains(row.getUuid("Instance")))return true;
        for(String key:row.getKeys()){var value=row.get(key);if(value instanceof NbtCompound child&&related(child,ids))return true;if(value instanceof NbtList list)for(var item:list)if(item instanceof NbtCompound child&&related(child,ids))return true;}return false;
    }
    private static void members(NbtCompound row,Set<UUID> ids){
        if(row.containsUuid("Instance"))ids.add(row.getUuid("Instance"));for(String key:row.getKeys()){var value=row.get(key);if(value instanceof NbtCompound child)members(child,ids);if(value instanceof NbtList list)for(var item:list)if(item instanceof NbtCompound child)members(child,ids);}
    }
    public static NbtCompound capture(MinecraftServer server,Collection<MechanismLinks.TargetRef> references,Collection<ToolTarget> nativeTargets){
        var full=all(server);Set<UUID> selected=new LinkedHashSet<>();references.forEach(r->selected.add(r.instance()));Set<UUID> affected=new LinkedHashSet<>(selected);boolean changed;
        do{int before=affected.size();for(String family:List.of("Rules","Groups"))for(var raw:full.getCompound(family).getList(family,10)){var row=(NbtCompound)raw;if(related(row,affected))members(row,affected);}changed=before!=affected.size();}while(changed);
        var result=new NbtCompound();NbtList objectRefs=new NbtList();references.forEach(r->objectRefs.add(r.write()));result.put("Selected",objectRefs);NbtList natives=new NbtList();nativeTargets.forEach(t->natives.add(t.write()));result.put("Native",natives);
        var links=full.getCompound("Links").copy();Set<String> targetKeys=new LinkedHashSet<>();for(var raw:links.getList("Targets",10)){var row=(NbtCompound)raw;if(related(row,affected))targetKeys.add(MechanismLinks.TargetRef.read(row.getCompound("Ref")).key());}
        links.put("Targets",filtered(links.getList("Targets",10),r->related(r,affected)));
        NbtList levers=new NbtList();for(var raw:full.getCompound("Links").getList("Levers",10)){var row=((NbtCompound)raw).copy();boolean source=affected.contains(row.getUuid("Id"));NbtList keys=new NbtList();for(var item:row.getList("Targets",8))if(source||targetKeys.contains(item.asString()))keys.add(item.copy());if(source||!keys.isEmpty()){row.put("Targets",keys);row.putBoolean("WorldEditFullLever",source);levers.add(row);}}
        links.put("Levers",levers);links.put("Removed",new NbtList());result.put("Links",links);
        var rules=full.getCompound("Rules").copy();NbtList ruleRows=filtered(rules.getList("Rules",10),r->related(r,affected));Set<UUID> ruleIds=new HashSet<>();for(var raw:ruleRows)ruleIds.add(((NbtCompound)raw).getUuid("Id"));rules.put("Rules",ruleRows);rules.put("Flags",filtered(rules.getList("Flags",10),r->affected.contains(r.getUuid("Id"))));rules.put("Queue",filtered(rules.getList("Queue",10),r->related(r,affected)||ruleIds.contains(r.getUuid("Rule"))));NbtList imported=new NbtList();for(var raw:rules.getList("Imported",11))if(affected.contains(uuid(raw)))imported.add(raw.copy());rules.put("Imported",imported);NbtList pending=new NbtList();for(var raw:rules.getList("MigrationImportedPending",8))if(targetKeys.contains(raw.asString()))pending.add(raw.copy());rules.put("MigrationImportedPending",pending);result.put("Rules",rules);
        var groups=full.getCompound("Groups").copy();groups.put("Groups",filtered(groups.getList("Groups",10),r->related(r,affected)));result.put("Groups",groups);
        var policies=full.getCompound("Policies").copy();policies.put("Entries",filtered(policies.getList("Entries",10),r->related(r,affected)));result.put("Policies",policies);
        Set<String> toolKeys=new HashSet<>();references.forEach(r->toolKeys.add(ToolTarget.mechanism(r).key()));nativeTargets.forEach(t->toolKeys.add(t.key()));var commands=full.getCompound("Commands").copy();commands.put("Entries",filtered(commands.getList("Entries",10),r->toolKeys.contains(ToolTarget.read(r.getCompound("Target")).key())));result.put("Commands",commands);return result;
    }
    private static String identity(NbtCompound row,String family){
        return switch(family){case "Targets"->MechanismLinks.TargetRef.read(row.getCompound("Ref")).key();case "Policies"->row.contains("AssemblyStorageKey",8)?row.getString("AssemblyStorageKey"):MechanismLinks.TargetRef.read(row.getCompound("Ref")).key();case "Commands"->row.contains("AssemblyStorageKey",8)?row.getString("AssemblyStorageKey"):ToolTarget.read(row.getCompound("Target")).key();case "Queue"->Long.toString(row.getLong("Number"));default->row.getUuid("Id").toString();};
    }
    private static void merge(NbtCompound current,NbtCompound incoming,String field,String family){var map=new LinkedHashMap<String,NbtCompound>();for(var raw:current.getList(field,10)){var row=(NbtCompound)raw;map.put(identity(row,family),row.copy());}for(var raw:incoming.getList(field,10)){var row=((NbtCompound)raw).copy();String id=identity(row,family);if(family.equals("Levers")&&!row.getBoolean("WorldEditFullLever")&&map.containsKey(id)){var existing=map.get(id);LinkedHashSet<String> keys=new LinkedHashSet<>();for(var key:existing.getList("Targets",8))keys.add(key.asString());for(var key:row.getList("Targets",8))keys.add(key.asString());NbtList list=new NbtList();keys.forEach(k->list.add(NbtString.of(k)));existing.put("Targets",list);continue;}row.remove("WorldEditFullLever");map.put(id,row);}if(map.size()>4096)throw new IllegalStateException("WorldEdit reference capacity exceeded: "+family);NbtList list=new NbtList();map.values().forEach(list::add);current.put(field,list);}
    private static void union(NbtCompound current,NbtCompound incoming,String field,int type){var set=new LinkedHashSet<NbtElement>();current.getList(field,type).forEach(e->set.add(e.copy()));incoming.getList(field,type).forEach(e->set.add(e.copy()));if(set.size()>4096)throw new IllegalStateException("WorldEdit reference capacity exceeded: "+field);var list=new NbtList();set.forEach(list::add);current.put(field,list);}
    private static void prune(NbtCompound current,NbtCompound captured){
        for(String family:List.of("Links","Rules","Groups","Policies","Commands")){var destination=current.getCompound(family);var removed=captured.getCompound(family);for(String field:family.equals("Links")?List.of("Targets"):family.equals("Rules")?List.of("Rules","Flags","Queue"):family.equals("Groups")?List.of("Groups"):List.of("Entries")){String kind=field.equals("Entries")?family:field;Set<String> keys=new HashSet<>();for(var raw:removed.getList(field,10))keys.add(identity((NbtCompound)raw,kind));destination.put(field,filtered(destination.getList(field,10),row->!keys.contains(identity(row,kind))));}}
        Set<String> targetKeys=new HashSet<>();for(var raw:captured.getCompound("Links").getList("Targets",10))targetKeys.add(MechanismLinks.TargetRef.read(((NbtCompound)raw).getCompound("Ref")).key());Set<UUID> sourceIds=new HashSet<>();for(var raw:captured.getList("Selected",10))sourceIds.add(MechanismLinks.TargetRef.read((NbtCompound)raw).instance());NbtList levers=new NbtList();for(var raw:current.getCompound("Links").getList("Levers",10)){var row=((NbtCompound)raw).copy();if(sourceIds.contains(row.getUuid("Id")))continue;NbtList list=new NbtList();for(var key:row.getList("Targets",8))if(!targetKeys.contains(key.asString()))list.add(key.copy());row.put("Targets",list);levers.add(row);}current.getCompound("Links").put("Levers",levers);
    }
    private static void remap(NbtCompound row,Map<UUID,UUID> objects,BlockPos delta){
        if(row.containsUuid("Instance")&&objects.containsKey(row.getUuid("Instance"))){row.putUuid("Instance",objects.get(row.getUuid("Instance")));if(row.contains("Root",4))row.putLong("Root",BlockPos.fromLong(row.getLong("Root")).add(delta).asLong());}
        if(row.containsUuid("UUID")&&row.contains("Kind",8)&&objects.containsKey(row.getUuid("UUID"))){row.putUuid("UUID",objects.get(row.getUuid("UUID")));if(row.contains("Root",4))row.putLong("Root",BlockPos.fromLong(row.getLong("Root")).add(delta).asLong());}
        for(String key:new ArrayList<>(row.getKeys())){var value=row.get(key);if(value instanceof NbtCompound child)remap(child,objects,delta);if(value instanceof NbtList list)for(var item:list)if(item instanceof NbtCompound child)remap(child,objects,delta);}
    }
    /** Prepared before world mutation; applying afterwards cannot drop rows at
     * limits or overwrite an unrelated component changed since clipboard copy. */
    public static final class Prepared {private final MinecraftServer server;private final NbtCompound after;private Prepared(MinecraftServer server,NbtCompound after){this.server=server;this.after=after;}public void apply(){var links=MechanismState.get(server);var restored=MechanismState.fromNbt(after.getCompound("Links"));links.levers.clear();links.levers.putAll(restored.levers);links.targets.clear();links.targets.putAll(restored.targets);links.removed.clear();links.removed.addAll(restored.removed);links.revision=restored.revision;links.markDirty();MechanismRules.restoreMigration(server,after.getCompound("Rules"));MechanismGroups.restoreMigration(server,after.getCompound("Groups"));ObjectPolicies.restoreMigration(server,after.getCompound("Policies"));ToolCommands.restoreAssemblyMigration(server,after.getCompound("Commands"));}}
    public static Prepared prepare(MinecraftServer server,NbtCompound saved,Map<UUID,UUID> objects,BlockPos delta,BiFunction<String,UUID,UUID> extraIds,Collection<MechanismLinks.TargetRef> removed,Collection<ToolTarget> removedNative){
        if(!server.isOnThread())throw new IllegalStateException("WorldEdit reference restore requires server thread");var incoming=saved.copy();var current=all(server);prune(current,capture(server,removed,removedNative));boolean copy=!delta.equals(BlockPos.ORIGIN);Map<String,String> keys=new LinkedHashMap<>();for(var raw:saved.getList("Selected",10)){var before=MechanismLinks.TargetRef.read((NbtCompound)raw);var row=before.write();remap(row,objects,delta);keys.put(before.key(),MechanismLinks.TargetRef.read(row).key());}for(String family:List.of("Links","Rules","Groups","Policies","Commands"))remap(incoming.getCompound(family),objects,delta);
        var links=incoming.getCompound("Links");for(var raw:links.getList("Levers",10)){var row=(NbtCompound)raw;UUID old=row.getUuid("Id");if(objects.containsKey(old)){row.putUuid("Id",objects.get(old));row.putLong("Pos",BlockPos.fromLong(row.getLong("Pos")).add(delta).asLong());}var out=new NbtList();for(var key:row.getList("Targets",8))out.add(NbtString.of(keys.getOrDefault(key.asString(),key.asString())));row.put("Targets",out);}
        var rules=incoming.getCompound("Rules");Map<UUID,UUID> ruleIds=new HashMap<>();long creation=current.getCompound("Rules").getLong("Creation"),sequence=current.getCompound("Rules").getLong("Sequence");if(copy){for(var raw:rules.getList("Rules",10)){var row=(NbtCompound)raw;UUID old=row.getUuid("Id"),next=objects.getOrDefault(old,extraIds.apply("rule",old));ruleIds.put(old,next);row.putUuid("Id",next);row.putLong("Order",++creation);}for(var raw:rules.getList("Flags",10)){var row=(NbtCompound)raw;if(objects.containsKey(row.getUuid("Id")))row.putUuid("Id",objects.get(row.getUuid("Id")));}NbtList imported=new NbtList();for(var raw:rules.getList("Imported",11))imported.add(NbtHelper.fromUuid(objects.getOrDefault(uuid(raw),uuid(raw))));rules.put("Imported",imported);for(var raw:rules.getList("Queue",10)){var row=(NbtCompound)raw;row.putLong("Number",++sequence);row.putUuid("Rule",ruleIds.getOrDefault(row.getUuid("Rule"),row.getUuid("Rule")));}for(var raw:incoming.getCompound("Groups").getList("Groups",10)){var row=(NbtCompound)raw;row.putUuid("Id",extraIds.apply("group",row.getUuid("Id")));NbtList active=new NbtList();for(var id:row.getList("Active",11))active.add(NbtHelper.fromUuid(objects.getOrDefault(uuid(id),uuid(id))));row.put("Active",active);}}
        for(var raw:incoming.getCompound("Commands").getList("Entries",10)){var row=(NbtCompound)raw;var ref=ToolTarget.read(row.getCompound("Target"));if(copy&&ref.kind()==ToolTarget.Kind.BLOCK)row.put("Target",new ToolTarget(ref.kind(),ref.dimension(),null,BlockPos.fromLong(ref.root()).add(delta).asLong(),ref.registry()).write());if(copy&&row.contains("AssemblyStorageKey",8))row.putString("AssemblyStorageKey","assembly:we:"+extraIds.apply("command",UUID.nameUUIDFromBytes(row.getString("AssemblyStorageKey").getBytes(java.nio.charset.StandardCharsets.UTF_8))));}
        if(copy)for(var raw:incoming.getCompound("Policies").getList("Entries",10)){var row=(NbtCompound)raw;if(row.contains("AssemblyStorageKey",8))row.putString("AssemblyStorageKey","assembly:we:"+extraIds.apply("policy",UUID.nameUUIDFromBytes(row.getString("AssemblyStorageKey").getBytes(java.nio.charset.StandardCharsets.UTF_8))));}
        var destLinks=current.getCompound("Links");merge(destLinks,links,"Targets","Targets");merge(destLinks,links,"Levers","Levers");Set<String> restoredKeys=new HashSet<>();for(var raw:links.getList("Targets",10))restoredKeys.add(MechanismLinks.TargetRef.read(((NbtCompound)raw).getCompound("Ref")).key());var remainingTombstones=new NbtList();for(var raw:destLinks.getList("Removed",8))if(!restoredKeys.contains(raw.asString()))remainingTombstones.add(raw.copy());destLinks.put("Removed",remainingTombstones);destLinks.putLong("Revision",Math.max(destLinks.getLong("Revision"),links.getLong("Revision")));
        var destRules=current.getCompound("Rules");merge(destRules,rules,"Rules","Rules");merge(destRules,rules,"Flags","Flags");merge(destRules,rules,"Queue","Queue");union(destRules,rules,"Imported",11);NbtList barriers=new NbtList();for(var raw:rules.getList("MigrationImportedPending",8))barriers.add(NbtString.of(keys.getOrDefault(raw.asString(),raw.asString())));rules.put("MigrationImportedPending",barriers);union(destRules,rules,"MigrationImportedPending",8);destRules.putLong("Sequence",Math.max(sequence,Math.max(destRules.getLong("Sequence"),rules.getLong("Sequence"))));destRules.putLong("Creation",Math.max(creation,Math.max(destRules.getLong("Creation"),rules.getLong("Creation"))));merge(current.getCompound("Groups"),incoming.getCompound("Groups"),"Groups","Groups");merge(current.getCompound("Policies"),incoming.getCompound("Policies"),"Entries","Policies");merge(current.getCompound("Commands"),incoming.getCompound("Commands"),"Entries","Commands");return new Prepared(server,current);
    }
}
